package export

import "strings"

type Account struct {
	Holder string
	IBAN   string
}


func row(a Account) []string {
	return []string{a.Holder, maskIBAN(a.IBAN)}
}

// maskIBAN keeps the last four characters and hides the rest.
func maskIBAN(iban string) string {
	if len(iban) <= 4 {
		return iban
	}
	return strings.Repeat("*", len(iban)-4) + iban[len(iban)-4:]
}
